//
//  TerminalSurface.swift
//  iSH+
//
//  The native terminal (SwiftTerm) that replaced the hterm/WKWebView terminal.
//  Each Terminal session owns one surface for its whole life, so output keeps
//  being processed while the session is not on screen; TerminalView hosts
//  whichever session's surface is current.
//

import UIKit
import SwiftTerm

@objc(ISHTerminalSurfaceHost)
public protocol TerminalSurfaceHost: AnyObject {
    /// Bytes typed by the user or generated by the terminal (mouse reports, replies).
    func surfaceSendInput(_ data: Data)
    /// The grid size changed (rotation, font size, split view, ...).
    func surfaceDidResize(columns: Int, rows: Int)
    func surfaceSetTitle(_ title: String)
    func surfaceOpenLink(_ link: String)
}

@objc(ISHTerminalSurface)
public final class TerminalSurface: TerminalView, TerminalViewDelegate {
    @objc public weak var host: TerminalSurfaceHost?

    /// The Ctrl button of the iSH key bar. Holding or toggling it turns the
    /// next typed character into a control character.
    @objc public weak var controlKey: UIButton?

    @objc public var backtickMapsEscape = false
    @objc public var overrideControlSpace = false
    @objc public var optionSendsEscape: Bool {
        get { optionAsMetaKey }
        set { optionAsMetaKey = newValue }
    }

    /// Lets a host's input accessory replace SwiftTerm's own bar.
    @objc public var accessoryView: UIView? {
        get { inputAccessoryView }
        set { inputAccessoryView = newValue }
    }

    @objc public init(frame: CGRect, fontSize: CGFloat) {
        super.init(frame: frame, font: UIFont.monospacedSystemFont(ofSize: fontSize, weight: .regular))
        terminalDelegate = self
        inputAccessoryView = nil
        backgroundColor = .clear
        allowMouseReporting = true
        linkReporting = .implicit
        changeScrollback(10_000)
    }

    required init?(coder: NSCoder) {
        fatalError("TerminalSurface is created in code")
    }

    // MARK: State for Objective-C

    @objc public var applicationCursor: Bool {
        terminalInputStateSnapshot()?.applicationCursor ?? false
    }

    @objc public var columns: Int { terminalDimensions.cols }
    @objc public var rows: Int { terminalDimensions.rows }

    @objc public func feedData(_ data: Data) {
        data.withUnsafeBytes { raw in
            feed(byteArray: ArraySlice(raw.bindMemory(to: UInt8.self)))
        }
    }

    @objc public func scrollToBottom() {
        scroll(toPosition: 1)
    }

    @objc public func clearScrollbackBuffer() {
        clearScrollback()
    }

    // MARK: Styling

    /// `cursorShape`: 0 block, 1 bar, 2 underline (matches CursorStyle in UserPreferences.h).
    @objc public func applyStyle(font: UIFont,
                                 foreground: UIColor,
                                 background: UIColor,
                                 cursor: UIColor?,
                                 palette: [UIColor]?,
                                 cursorShape: Int,
                                 blink: Bool) {
        if self.font != font {
            self.font = font
        }
        nativeForegroundColor = foreground
        nativeBackgroundColor = background
        caretColor = cursor ?? foreground
        installColors((palette?.count == 16 ? palette! : TerminalSurface.xtermPalette).map(TerminalSurface.color(from:)))

        let style: CursorStyle
        switch (cursorShape, blink) {
        case (1, true): style = .blinkBar
        case (1, false): style = .steadyBar
        case (2, true): style = .blinkUnderline
        case (2, false): style = .steadyUnderline
        case (_, true): style = .blinkBlock
        default: style = .steadyBlock
        }
        setCursorStyle(style)
    }

    static let xtermPalette: [UIColor] = [
        0x000000, 0xcd0000, 0x00cd00, 0xcdcd00, 0x0000ee, 0xcd00cd, 0x00cdcd, 0xe5e5e5,
        0x7f7f7f, 0xff0000, 0x00ff00, 0xffff00, 0x5c5cff, 0xff00ff, 0x00ffff, 0xffffff,
    ].map { rgb in
        UIColor(red: CGFloat((rgb >> 16) & 0xff) / 255,
                green: CGFloat((rgb >> 8) & 0xff) / 255,
                blue: CGFloat(rgb & 0xff) / 255, alpha: 1)
    }

    static func color(from color: UIColor) -> SwiftTerm.Color {
        var r: CGFloat = 0, g: CGFloat = 0, b: CGFloat = 0, a: CGFloat = 0
        color.getRed(&r, green: &g, blue: &b, alpha: &a)
        func c(_ v: CGFloat) -> UInt16 { UInt16(max(0, min(1, v)) * 65535) }
        return SwiftTerm.Color(red: c(r), green: c(g), blue: c(b))
    }

    // MARK: Focus

    /// Called after the surface gains or loses keyboard focus.
    @objc public var focusChanged: ((Bool) -> Void)?

    public override func becomeFirstResponder() -> Bool {
        let result = super.becomeFirstResponder()
        focusChanged?(isFirstResponder)
        return result
    }

    public override func resignFirstResponder() -> Bool {
        let result = super.resignFirstResponder()
        focusChanged?(isFirstResponder)
        return result
    }

    // MARK: Keyboard

    public override func insertText(_ text: String) {
        if let controlKey {
            if controlKey.isHighlighted {
                controlKey.isSelected = true
            }
            if controlKey.isSelected {
                if !controlKey.isHighlighted {
                    controlKey.isSelected = false
                }
                if let byte = TerminalSurface.controlByte(for: text) {
                    send([byte])
                    return
                }
            }
        }
        super.insertText(text)
    }

    /// Ctrl+key mapping used by the on-screen Ctrl button (same table as old iSH).
    static func controlByte(for text: String) -> UInt8? {
        guard text.count == 1, let scalar = text.unicodeScalars.first, scalar.isASCII else { return nil }
        var ch = UInt8(scalar.value)
        switch ch {
        case UInt8(ascii: " "): return 0
        case UInt8(ascii: "2"): ch = UInt8(ascii: "@")
        case UInt8(ascii: "6"): ch = UInt8(ascii: "^")
        case UInt8(ascii: "-"): ch = UInt8(ascii: "_")
        default: break
        }
        guard "abcdefghijklmnopqrstuvwxyz@^_=[]\\".utf8.contains(ch) || (ch >= 0x40 && ch < 0x60) else {
            return nil
        }
        if ch >= UInt8(ascii: "a") && ch <= UInt8(ascii: "z") {
            ch -= 0x20
        }
        return ch ^ 0x40
    }

    public override func pressesBegan(_ presses: Set<UIPress>, with event: UIPressesEvent?) {
        if presses.count == 1, let key = presses.first?.key {
            let mods = key.modifierFlags.intersection([.shift, .control, .alternate, .command])
            if backtickMapsEscape, key.keyCode == .keyboardGraveAccentAndTilde, mods.isEmpty {
                send([0x1b])
                return
            }
            if overrideControlSpace, key.keyCode == .keyboardSpacebar, mods == .control {
                send([0])
                return
            }
        }
        super.pressesBegan(presses, with: event)
    }

    // MARK: TerminalViewDelegate

    public func sizeChanged(source: TerminalView, newCols: Int, newRows: Int) {
        host?.surfaceDidResize(columns: newCols, rows: newRows)
    }

    public func setTerminalTitle(source: TerminalView, title: String) {
        host?.surfaceSetTitle(title)
    }

    public func hostCurrentDirectoryUpdate(source: TerminalView, directory: String?) {}

    public func send(source: TerminalView, data: ArraySlice<UInt8>) {
        host?.surfaceSendInput(Data(data))
    }

    public func scrolled(source: TerminalView, position: Double) {}

    public func rangeChanged(source: TerminalView, startY: Int, endY: Int) {}

    public func requestOpenLink(source: TerminalView, request: TerminalLinkRequest) {
        host?.surfaceOpenLink(request.link)
    }

    public func clipboardCopy(source: TerminalView, content: Data) {
        if let string = String(data: content, encoding: .utf8) {
            UIPasteboard.general.string = string
        }
    }
}
